### Python
```py
from collections import Counter
T = int(input())
for _ in range(T):
    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    d = Counter(a)
    v = []
    for kk, val in d.items():
        v.append((val, kk))
    v.sort()
    t = 0
    res = 0
    cnt = len(v)
    for L, R in v:
        cnt -= 1
        if L + t + cnt * L >= k:
            res = max(res, R) 
        t += L
    print(res)

